'use client';

import { useRef, useEffect, Fragment } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import {
  CREDIBILITY_BRANDS,
  CREDIBILITY_AWARDS,
  CREDIBILITY_PRESS,
  CREDIBILITY_STATS,
  type CredibilityBrand,
} from '@/lib/content';

gsap.registerPlugin(ScrollTrigger);

/* ── Accent color mapping ─────────────────────────────────── */
const ACCENT_BORDER: Record<CredibilityBrand['accent'], string> = {
  magenta: 'var(--accent)',
  gold: 'var(--accent-secondary)',
  cerulean: 'var(--accent-tertiary)',
};

/* ── Inline SVG trophy icon ───────────────────────────────── */
function TrophyIcon({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6" />
      <path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18" />
      <path d="M4 22h16" />
      <path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20 7 22" />
      <path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20 17 22" />
      <path d="M18 2H6v7a6 6 0 0 0 12 0V2Z" />
    </svg>
  );
}

/* ── Brand Logo ───────────────────────────────────────────── */
function BrandLogo({ brand }: { brand: CredibilityBrand }) {
  return (
    <div
      className="cred-card group flex items-center justify-center rounded-lg px-6 py-5 transition-all duration-300"
      style={{ borderBottom: `2px solid ${ACCENT_BORDER[brand.accent]}` }}
    >
      <img
        src={brand.logo}
        alt={brand.name}
        className="h-8 w-auto max-w-full object-contain opacity-60 transition-opacity duration-300 group-hover:opacity-100 md:h-9"
        loading="lazy"
      />
    </div>
  );
}

/* ── Stat Block ───────────────────────────────────────────── */
function StatBlock({ value, label }: { value: string; label: string }) {
  return (
    <div className="cred-stat flex flex-col items-center text-center">
      <span className="font-heading text-2xl font-bold text-text-primary md:text-3xl">
        {value}
      </span>
      <span className="mt-1 font-mono text-[11px] uppercase tracking-[0.15em] text-text-tertiary">
        {label}
      </span>
    </div>
  );
}

/* ── Main Section ─────────────────────────────────────────── */
export default function CredibilityGrid() {
  const sectionRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;

    const prefersReducedMotion = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches;

    if (prefersReducedMotion) {
      gsap.set(
        el.querySelectorAll(
          '.cred-header, .cred-rule, .cred-card, .cred-stat, .cred-award, .cred-press-logo',
        ),
        { opacity: 1, y: 0, x: 0 },
      );
      return;
    }

    const ctx = gsap.context(() => {
      // Header + rule slide in from left
      gsap.fromTo(
        el.querySelectorAll('.cred-header, .cred-rule'),
        { opacity: 0, x: -24 },
        {
          opacity: 1,
          x: 0,
          duration: 0.6,
          ease: 'power3.out',
          stagger: 0.08,
          scrollTrigger: {
            trigger: el,
            start: 'top 88%',
            toggleActions: 'play none none reverse',
          },
        },
      );

      // Brand logos staggered fade-up
      gsap.fromTo(
        el.querySelectorAll('.cred-card'),
        { opacity: 0, y: 20 },
        {
          opacity: 1,
          y: 0,
          duration: 0.5,
          ease: 'power3.out',
          stagger: 0.06,
          scrollTrigger: {
            trigger: el.querySelector('.cred-grid'),
            start: 'top 90%',
            toggleActions: 'play none none reverse',
          },
        },
      );

      // Stats fade up
      gsap.fromTo(
        el.querySelectorAll('.cred-stat'),
        { opacity: 0, y: 16 },
        {
          opacity: 1,
          y: 0,
          duration: 0.5,
          ease: 'power3.out',
          stagger: 0.1,
          scrollTrigger: {
            trigger: el.querySelector('.cred-stats'),
            start: 'top 92%',
            toggleActions: 'play none none reverse',
          },
        },
      );

      // Awards + press logos fade in
      gsap.fromTo(
        el.querySelectorAll('.cred-award, .cred-press-logo'),
        { opacity: 0, y: 10 },
        {
          opacity: 1,
          y: 0,
          duration: 0.45,
          ease: 'power3.out',
          stagger: 0.08,
          scrollTrigger: {
            trigger: el.querySelector('.cred-bottom'),
            start: 'top 94%',
            toggleActions: 'play none none reverse',
          },
        },
      );
    }, el);

    return () => {
      ctx.revert();
    };
  }, []);

  return (
    <section
      ref={sectionRef}
      aria-label="Credentials and clients"
      className="border-y border-border-subtle bg-bg-deep py-16 md:py-24"
    >
      <div className="mx-auto max-w-[1200px] px-6 md:px-12">
        {/* ── Header ─────────────────────────────────────── */}
        <div className="mb-10 flex items-center gap-4">
          <p className="cred-header shrink-0 font-mono text-[10px] uppercase tracking-[0.2em] text-text-tertiary">
            Trusted by
          </p>
          <div
            className="cred-rule h-px flex-1"
            style={{ background: 'var(--border-subtle)' }}
          />
        </div>

        {/* ── Brand Logo Grid ────────────────────────────── */}
        <div className="cred-grid grid grid-cols-2 gap-4 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6">
          {CREDIBILITY_BRANDS.map((brand) => (
            <BrandLogo key={brand.name} brand={brand} />
          ))}
        </div>

        {/* ── Stats Row ──────────────────────────────────── */}
        <div className="cred-stats mt-14 flex flex-wrap items-center justify-center gap-x-10 gap-y-6 border-y border-border-subtle py-8 md:gap-x-16">
          {CREDIBILITY_STATS.map((stat, i) => (
            <Fragment key={stat.label}>
              {i > 0 && (
                <span
                  className="hidden text-text-tertiary/30 md:inline"
                  aria-hidden="true"
                >
                  ·
                </span>
              )}
              <StatBlock value={stat.value} label={stat.label} />
            </Fragment>
          ))}
        </div>

        {/* ── Awards + Press ─────────────────────────────── */}
        <div className="cred-bottom mt-10 grid gap-8 md:grid-cols-2">
          {/* Awards */}
          <div>
            <p className="mb-4 font-mono text-[10px] uppercase tracking-[0.2em] text-text-tertiary">
              Recognition
            </p>
            <div className="flex flex-wrap gap-x-5 gap-y-3">
              {CREDIBILITY_AWARDS.map((award) => (
                <span
                  key={award.name}
                  className="cred-award inline-flex items-center gap-1.5"
                >
                  <TrophyIcon className="text-accent-secondary" />
                  <span className="font-heading text-sm font-medium text-text-primary">
                    {award.name}
                  </span>
                  <span className="font-mono text-[10px] uppercase tracking-wider text-text-tertiary">
                    {award.detail}
                  </span>
                </span>
              ))}
            </div>
          </div>

          {/* Press — logo row */}
          <div>
            <p className="mb-4 font-mono text-[10px] uppercase tracking-[0.2em] text-text-tertiary">
              Featured in
            </p>
            <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
              {CREDIBILITY_PRESS.map((pub) => (
                <img
                  key={pub.name}
                  src={pub.logo}
                  alt={pub.name}
                  className="cred-press-logo h-5 w-auto object-contain md:h-6"
                  loading="lazy"
                />
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
